{
  "title": "未知信号",
  "scene": "飞船内部的显示器闪烁着奇怪的蓝色光点，远处传来微弱的未知信号。你在一个漆黑的走廊中摸索，墙壁上的控制面板上散落着一些尚未用过的氧气罐和维修工具。周围的环境让人感到不安，但那信号似乎在召唤着你。",
  "goal": "找到并解读未知信号的来源以修复飞船。",
  "clue": "微弱的未知信号、显示器闪烁的蓝色光点、控制面板上散落的氧气罐和维修工具。",
  "choices": [
    {"id": "A", "text": "检查闪烁的显示器", "outcome": "你注意到显示器上有一个被遮挡的蓝色光点，似乎在指引某个方向。但你并未找到该方向的具体位置。", "result": "partial", "next": "retry"},
    {"id": "B", "text": "收集更多的氧气罐", "outcome": "你发现了一个隐藏的储藏室，里面装满了氧气罐，但也发现了几根奇怪的金属管。这些金属管可能是个线索，但你没时间带回飞船。", "result": "success", "next": "next_level"},
    {"id": "C", "text": "尝试使用维修工具修复显示器", "outcome": "你试图使用维修工具修复显示器，但没有成功。屏幕反而开始剧烈闪烁，发出刺耳的声音，导致你不得不暂时逃离现场，避免受到干扰。", "result": "fail", "next": "retry"}
  ]
}
